#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Checks once, against the real GitHub, what the tests can't: that commits made
# with a GitHub App *installation* token are credited on the user's contribution
# graph on the right UTC day. The spike (prototype/github-push-spike) proved
# this only with a user token. Covers both paths: a live Solution Commit
# (Contents API) and an Import (one git push of backdated commits).
#
# Run from the repo root after scripts/setup-github-app-dev.sh. Dev only: it
# backdates one submission in the local database.

ENV_FILE="infra/.env"
BACKDATE_DAYS=3
RESULTS=()

psql_dev() {
  docker exec -i codebite-postgres psql -U codebite -d codebite -v ON_ERROR_STOP=1 "$@"
}

utc_days_ago() {
  date -u -v-"$1"d +%Y-%m-%d 2>/dev/null || date -u -d "$1 days ago" +%Y-%m-%d
}

record() {
  if confirm "$1"; then RESULTS+=("PASS  $1"); else RESULTS+=("FAIL  $1"); SKIPPED+=("investigate: $1"); fi
}

run_wizard() {

TOTAL_STAGES=8

banner "Verify GitHub credits Solution Commits"

stage "Prerequisites"
say "You need the dev GitHub App registered and its values in $ENV_FILE."
missing=()
for k in GITHUB_APP_ID GITHUB_APP_CLIENT_ID GITHUB_APP_CLIENT_SECRET GITHUB_APP_SLUG GITHUB_APP_PRIVATE_KEY_BASE64; do
  grep -Eq "^(export )?${k}=.+" "$ENV_FILE" 2>/dev/null || missing+=("$k")
done
if (( ${#missing[@]} )); then
  warn "missing in $ENV_FILE: ${missing[*]}"
  say "Run scripts/setup-github-app-dev.sh first, then re-run this wizard."
  exit 1
fi
note "GITHUB_APP_* found in $ENV_FILE"
step "The App needs: Contents → Read and write, and 'Request user authorization (OAuth) during installation'"
ask GITHUB_LOGIN "Your GitHub username (whose graph we'll check):"
pause

stage "Create a scratch Solution Repository"
say "Commits only count on your graph in a repository you own that isn't a fork."
say "Make it public so the private-contributions setting doesn't matter."
open_url "https://github.com/new"
step "Name it e.g. codebite-solutions-check, Public"
step "Tick 'Add a README file' so the repository has a default branch"
step "Create repository"
ask SOLUTION_REPO "Repository name (without your username):"
pause

stage "Start CodeBite locally"
say "In separate terminals, from the repo root:"
step "docker compose -f infra/docker-compose.yml up -d"
step "source infra/.env && SPRING_PROFILES_ACTIVE=dev ./gradlew :backend:bootRun"
step "source infra/.env && ./gradlew :worker:bootRun     (needs Judge0 reachable at JUDGE0_URL)"
step "cd frontend && npm run dev"
pause "Press Enter once all four are up"
until curl -fsS http://localhost:8080/api/health >/dev/null 2>&1; do
  note "waiting for the backend on :8080 ..."; sleep 5
done
note "backend is up"
pause

stage "An Accepted submission from before the link"
say "This one will be Imported. Solve it before linking, then we backdate it."
open_url "http://localhost:5173/problems"
step "Sign in, open any problem, and Submit a correct solution until it says Accepted"
pause "Press Enter once it's Accepted"
say "Backdating your latest Accepted submission by $BACKDATE_DAYS days in the dev database."
if confirm "Run the UPDATE on codebite-postgres now?"; then
  psql_dev -c "UPDATE submissions SET created_at = created_at - interval '$BACKDATE_DAYS days'
               WHERE id = (SELECT id FROM submissions WHERE status = 'ACCEPTED' ORDER BY id DESC LIMIT 1)
               RETURNING id, created_at;"
else
  SKIPPED+=("backdate the pre-link submission (Import day check is meaningless without it)")
fi
pause

stage "Link GitHub"
open_url "http://localhost:5173/profile"
step "GitHub Link card → Link GitHub"
step "On GitHub: install on 'Only select repositories' → $SOLUTION_REPO → Install & Authorize"
step "Back on CodeBite the card shows $GITHUB_LOGIN/$SOLUTION_REPO"
pause "Press Enter once the card shows the linked repository"

stage "Live Solution Commit"
say "Solve a different problem now, so its square is today."
open_url "http://localhost:5173/problems"
step "Submit a correct solution until Accepted"
step "Submission detail should show the Solution Commit as Committed with a link"
step "Follow the link: the commit's author should be your avatar, not a bot"
record "Live Solution Commit shows Committed and is authored as you"
pause

stage "Import"
open_url "http://localhost:5173/profile"
step "GitHub Link card → Import → wait until it says Done"
open_url "https://github.com/$GITHUB_LOGIN/$SOLUTION_REPO/commits"
step "There should be an 'Accepted: …' commit dated $(utc_days_ago "$BACKDATE_DAYS") (author date)"
record "Imported commit landed, authored as you, dated $(utc_days_ago "$BACKDATE_DAYS")"
pause

stage "Contribution graph"
say "GitHub can take a few minutes to update the graph; reload if a square is still grey."
open_url "https://github.com/$GITHUB_LOGIN"
step "Hover today's square (UTC day $(utc_days_ago 0)): it should count the live commit"
record "Today's square ($(utc_days_ago 0) UTC) counts the live Solution Commit"
step "Hover the square for $(utc_days_ago "$BACKDATE_DAYS"): it should count the Imported commit"
record "The $(utc_days_ago "$BACKDATE_DAYS") square counts the Imported commit"

finish
say "Results:"
for r in "${RESULTS[@]}"; do note "  $r"; done
say "Paste these results as a comment on issue #18, then delete the scratch repository if you like."
printf '\n'
}

run_wizard "$@"; exit
